// ---- A) repair icon ink scaling in place ----
const repaired=[];
const iconComps = ws.findAll(n=>n.type==='COMPONENT'&&n.name.indexOf('Icon/')===0);
for (const c of iconComps) {
  const kids = c.children.filter(k=>k.type==='VECTOR'||k.type==='GROUP');
  if(!kids.length) continue;
  const minX=Math.min.apply(null,kids.map(k=>k.x));
  const minY=Math.min.apply(null,kids.map(k=>k.y));
  const maxX=Math.max.apply(null,kids.map(k=>k.x+k.width));
  const maxY=Math.max.apply(null,kids.map(k=>k.y+k.height));
  const inkW=maxX-minX, inkH=maxY-minY;
  if(!inkW||!inkH) continue;
  const targetW=c.width, targetH=c.height;
  const k=Math.min(targetW/inkW, targetH/inkH);
  if (Math.abs(k-1)<0.02) { repaired.push(c.name+':ok'); continue; }
  for(const v of kids){
    v.resize(Math.max(0.01,v.width*k), Math.max(0.01,v.height*k));
    v.x=(v.x-minX)*k; v.y=(v.y-minY)*k;
  }
  repaired.push(c.name+':x'+k.toFixed(2));
}

