// ---- absolute frame helper ----
function box(parent,name,o){
  o=o||{};
  const n=figma.createFrame();
  n.name=name;
  n.fills=o.fill?[paint(o.fill)]:(o.fills||[]);
  if(o.r!==undefined)n.cornerRadius=o.r;
  if(o.stroke){n.strokes=[paint(o.stroke)];n.strokeWeight=o.sw===undefined?1:o.sw;n.strokeAlign='INSIDE';}
  if(o.clip)n.clipsContent=true;
  parent.appendChild(n);
  n.resize(o.w===undefined?100:o.w,o.h===undefined?100:o.h);
  n.x=o.x||0;n.y=o.y||0;
  return n;
}
function comp(parent,name,w,h){
  const n=figma.createComponent();
  n.name=name;n.fills=[];parent.appendChild(n);n.resize(w,h);
  return n;
}
function txt(parent,o){
  const t=figma.createText();
  t.fontName=o.font||F.reg;t.characters=o.text||'';
  t.fontSize=o.size||16;
  if(o.lh)t.lineHeight={unit:'PIXELS',value:o.lh};
  t.fills=[paint(o.color||C.ink)];
  if(o.strike)t.textDecoration='STRIKETHROUGH';
  if(o.align)t.textAlignHorizontal=o.align;
  parent.appendChild(t);
  if(o.w){t.resize(o.w,t.height);t.textAutoResize='HEIGHT';}else t.textAutoResize='WIDTH_AND_HEIGHT';
  t.x=o.x||0;t.y=o.y||0;
  if(o.name)t.name=o.name;
  return t;
}
function spread(parent,items,x0,x1){
  const total=items.reduce((s,i)=>s+i.width,0);
  const gap=(x1-x0-total)/Math.max(1,items.length-1);
  let x=x0;
  for(const i of items){i.x=x;i.y=(i.y||0);x+=i.width+gap;}
}

// ---- icons from media library ----
const MEDIA={Account:'4:5',Arrow_Left:'4:4',Arrow_Right:'4:6',Cart:'4:7',Check:'4:8',Chevron_Down:'4:9',Chevron_Right:'4:10',Close:'4:11',Filter:'4:12',Minus:'4:13',Plus:'4:14',More:'4:15',Search:'4:16',Sparkle:'4:17',Star:'4:18',Star_Half:'4:19',Tag:'4:20',Trash:'4:21',Verified:'4:23'};
const BOX={Star:18,Star_Half:18,Sparkle:40,Check:14,Chevron_Down:16,Chevron_Right:16,Minus:16,Plus:16,More:20,Verified:20};
const iconIndex={};
const iconReport=[];
for (const name of Object.keys(MEDIA)) {
  const src=await figma.getNodeByIdAsync(MEDIA[name]);
  const b=BOX[name]||24;
  const c=comp(lib,'Icon/'+name,b,b);
  const inst=src.createInstance();
  inst.fills=[];
  c.appendChild(inst);
  inst.x=0;inst.y=0;
  try {
    const k=(b*0.88)/Math.max(src.width,src.height);
    inst.rescale(k);
  } catch(e) {
    const k=(b*0.88)/Math.max(inst.width,inst.height);
    inst.children.slice().forEach(ch=>{ch.resize(ch.width*k,ch.height*k);ch.x*=k;ch.y*=k;});
  }
  inst.x=Math.round((b-inst.width)/2);
  inst.y=Math.round((b-inst.height)/2);
  inst.findAll(v=>v.type==='VECTOR').forEach(v=>{
    v.fills=[paint(C.ink2)];
    if(v.strokes&&v.strokes.length)v.strokes=[paint(C.ink2)];
  });
  iconIndex[name]=c;
  c.x=40+((Object.keys(MEDIA).indexOf(name))%10)*110;
  c.y=40+Math.floor(Object.keys(MEDIA).indexOf(name)/10)*90;
  iconReport.push(name+'='+Math.round(inst.width)+'x'+Math.round(inst.height));
}
function icon(parent,name,size,color){
  const c=iconIndex[name];
  const i=c.createInstance();
  if(size&&size!==c.width)i.rescale(size/c.width);
  const col=color||C.ink2;
  i.findAll(v=>v.type==='VECTOR').forEach(v=>{v.fills=[paint(col)];if(v.strokes&&v.strokes.length)v.strokes=[paint(col)];});
  parent.appendChild(i);
  i.x=0;i.y=0;
  return i;
}
function starRow(parent,x,y,score,size,color){
  const full=Math.floor(score), half=(score-full)>=0.5;
  const step=(size||18)+6;
  for(let i=0;i<5;i++){
    let kind='Star', col=(size&&color)||C.rating;
    if(i<full) col=color||C.rating;
    else if(i===full&&half){kind='Star_Half';col=color||C.rating;}
    else col=C.empty;
    const s=icon(parent,kind,size||18,col);
    s.x=x+i*step; s.y=y;
  }
  return 5*step-6;
}

