function starRow(parent,x,y,score,size){
  const full=Math.floor(score),half=(score-full)>=0.5;
  for(let i=0;i<5;i++){
    let nm='Icon/Star',col=C.rating;
    if(i<full) col=C.rating;
    else if(i===full&&half){nm='Icon/Star_Half';col=C.rating;}
    else col='#D9D9DE';
    const s=inst(nm,parent,x+i*((size||18)+5),y);
    s.rescale((size||18)/s.width);
    s.findAll(v=>v.type==='VECTOR').forEach(v=>{v.fills=[paint(col)];if(v.strokes&&v.strokes.length)v.strokes=[paint(col)];});
  }
}

