function hit(parent,x,y,w,h,name,dest){
  const r=figma.createRectangle();
  r.name=name; r.fills=[paint('#FFFFFF',0.002)];
  parent.appendChild(r); r.resize(w,h); r.x=x; r.y=y;
  if(dest){
    r.reactions=[{trigger:{type:'ON_CLICK'},actions:[{type:'NODE',navigation:'NAVIGATE',destinationId:dest.id,transition:null,preserveScrollPosition:false}]}];
  }
  return r;
}
let links=0;
function safe(dest){ try{ return dest; }catch(e){ return null; } }
// iterate children of each frame, wrap clicked things
function wireCards(frame,dest){
  if(!frame||!dest) return 0;
  let n=0;
  frame.findAll(x=>x.type==='INSTANCE'&&x.name.indexOf('Card · ')===0).forEach(function(c){
    const bb=c.absoluteBoundingBox, fb=frame.absoluteBoundingBox;
    try{
      hit(frame, bb.x-fb.x, bb.y-fb.y, bb.width, bb.height, 'Hotspot · Card', dest);
      n++;
    }catch(e){}
  });
  return n;
}
